package com.healthwise.auth.controller;
import com.healthwise.auth.dto.AuthDtos.*; import com.healthwise.auth.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
/** Public authentication endpoints. */
@RestController @RequestMapping("/api/v1/auth") public class AuthController {private final AuthService service;public AuthController(AuthService s){service=s;}@PostMapping("/register")@ResponseStatus(HttpStatus.CREATED) public Tokens register(@Valid @RequestBody Register r){return service.register(r);}@PostMapping("/login")public Tokens login(@Valid @RequestBody Login r){return service.login(r);}@PostMapping("/refresh")public Tokens refresh(@Valid @RequestBody Refresh r){return service.refresh(r.refreshToken());}@PostMapping("/logout")@ResponseStatus(HttpStatus.NO_CONTENT)public void logout(@RequestBody(required=false) Refresh r){service.logout(r==null?null:r.refreshToken());}}
